# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">FIKIH USULÜNÜN TEMEL KAVRAMLARI: MÜKELLEF, EHLİYET VE MEKÂSID</text>\n  <rect x="22" y="40" width="320" height="178" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="62" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">ŞÂRİ, MÜKELLEF VE EHLİYET TÜRLERİ</text>\n  <text x="34" y="85" font-size="11.2" fill="#1e3a8a">• Şâri: Hüküm koyucu (Yüce Allah ve açıklayıcı Hz. Peygamber).</text>\n  <text x="34" y="110" font-size="11.2" fill="#1e3a8a">• Mükellef: Akıllı (âkıl) ve ergen (bâliğ) sorumlu birey.</text>\n  <text x="34" y="135" font-size="11.2" fill="#1e3a8a">• Vücup Ehliyeti: Haklara sahip olma (doğumla başlar).</text>\n  <text x="34" y="160" font-size="11.2" fill="#1e3a8a">• Eda Ehliyeti: Fiil ve ibadet sorumluluğu (akıl + buluğ).</text>\n  <text x="34" y="185" font-size="11.2" fill="#1e3a8a">• Nas: Kur\'an ayetleri ve Hz. Peygamber\'in hadis metinleri.</text>\n  <rect x="358" y="40" width="320" height="178" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="518" y="62" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#92400e">MEKÂSIDÜ\'Ş-ŞERİA (KORUNAN 5 TEMEL DEĞER)</text>\n  <text x="370" y="85" font-size="11.2" fill="#78350f">• 1. Dinin Korunması (Hıfzu\'d-Dîn): İnanç ve ibadet hürriyeti.</text>\n  <text x="370" y="110" font-size="11.2" fill="#78350f">• 2. Canın Korunması (Hıfzu\'n-Nefs): Yaşama hakkı, can güvenliği.</text>\n  <text x="370" y="135" font-size="11.2" fill="#78350f">• 3. Aklın Korunması (Hıfzu\'l-Akl): Sarhoş edicilerin yasağı.</text>\n  <text x="370" y="160" font-size="11.2" fill="#78350f">• 4. Neslin Korunması (Hıfzu\'n-Nesl): Nikâh ve aile kurumu.</text>\n  <text x="370" y="185" font-size="11.2" fill="#78350f">• 5. Malın Korunması (Hıfzu\'l-Mâl): Helal kazanç, hırsızlık yasağı.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">İslam hukukunda hükümler, maslahatı (faydayı) celbetmek ve mefsedeti (zararı) defetmek için konulmuştur.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">EF\'ÂL-İ MÜKELLEFÎN I: YAPILMASI İSTENEN VE SERBEST OLAN FİİLLER</text>\n  <rect x="22" y="40" width="320" height="178" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="182" y="62" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">FARZ VE VACİP (KESİN TALEPLER)</text>\n  <text x="34" y="85" font-size="11.2" fill="#14532d">• Farz: Kesin (kat\'î) delille emredilenler (İnkârı küfürdür).</text>\n  <text x="34" y="110" font-size="11.2" fill="#14532d">• • Farz-ı Ayn: Beş vakit namaz, Ramazan orucu, zekât.</text>\n  <text x="34" y="135" font-size="11.2" fill="#14532d">• • Farz-ı Kifâye: Cenaze namazı, hafızlık, tıp/mühendislik.</text>\n  <text x="34" y="160" font-size="11.2" fill="#14532d">• Vacip (Hanefi): Zannî delille kesin emredilenler.</text>\n  <text x="34" y="185" font-size="11.2" fill="#14532d">• • Vacip Örnekleri: Vitir ve bayram namazları, fitre, kurban.</text>\n  <rect x="358" y="40" width="320" height="178" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="518" y="62" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">SÜNNET, MÜSTEHAP VE MÜBAH</text>\n  <text x="370" y="85" font-size="11.2" fill="#1e3a8a">• Sünnet-i Müekkede: Peygamberimizin devamlı yaptığı sünnetler.</text>\n  <text x="370" y="110" font-size="11.2" fill="#1e3a8a">• • Örnek: Sabah ve öğle namazı sünnetleri, ezan, kamet.</text>\n  <text x="370" y="135" font-size="11.2" fill="#1e3a8a">• Sünnet-i Gayr-i Müekkede (Müstehap): Bazen yapılanlar.</text>\n  <text x="370" y="160" font-size="11.2" fill="#1e3a8a">• • Örnek: İkindi ve yatsının ilk sünneti, kuşluk namazı.</text>\n  <text x="370" y="185" font-size="11.2" fill="#1e3a8a">• Mübah: Yapılıp yapılmamasında serbest bırakılan helaller.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Hanefi mezhebi dışındaki çoğunluk (Cumhur) mezheplerde farz ile vacip eş anlamlı kabul edilir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">YASAKLANAN FİİLLER (HARAM - MEKRUH) VE VAZ\'Î HÜKÜMLER</text>\n  <rect x="22" y="40" width="320" height="178" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="182" y="62" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#6b21a8">HARAM VE MEKRUH (KAÇINILMASI İSTENENLER)</text>\n  <text x="34" y="85" font-size="11.2" fill="#581c87">• Haram: Kesin (kat\'î) delille yasaklanan fiillerdir.</text>\n  <text x="34" y="110" font-size="11.2" fill="#581c87">• • Li-aynihî Haram: Özü kötü olanlar (İçki, kumar, hırsızlık).</text>\n  <text x="34" y="135" font-size="11.2" fill="#581c87">• • Li-gayrihî Haram: Dış sebeple yasaklananlar (Cuma vakti ticaret).</text>\n  <text x="34" y="160" font-size="11.2" fill="#581c87">• Tahrîmen Mekruh: Harama yakın hoş görülmeyenler.</text>\n  <text x="34" y="185" font-size="11.2" fill="#581c87">• Tenzîhen Mekruh: Helale yakın hoş görülmeyen davranışlar.</text>\n  <rect x="358" y="40" width="320" height="178" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="518" y="62" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#9a3412">VAZ\'Î HÜKÜMLER (GEÇERLİLİK VE KOLAYLIK)</text>\n  <text x="370" y="85" font-size="11.2" fill="#7c2d12">• Sebep: Hükmün varlığına alamet olan durum (Vaktin girmesi).</text>\n  <text x="370" y="110" font-size="11.2" fill="#7c2d12">• Şart: İbadetin dışındaki zorunlu unsur (Namazda abdest).</text>\n  <text x="370" y="135" font-size="11.2" fill="#7c2d12">• Rükün: İbadetin içindeki zorunlu unsur (Rükû, secde).</text>\n  <text x="370" y="160" font-size="11.2" fill="#7c2d12">• Azimet ve Ruhsat: Normal hüküm ve mazerete bağlı kolaylık.</text>\n  <text x="370" y="185" font-size="11.2" fill="#7c2d12">• Sahih ve Bâtıl: Şartları tam (geçerli) ve geçersiz işlem.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">İbadetin dışındaki farzlara \'şart\' (namazın şartları), içindeki farzlara ise \'rükün\' (namazın rükünleri) denir.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
